package dev.cheeseowl.gmbg;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicInteger;

/** Synthetic row/bridge/query state fixtures; no Android/QSB execution. */
public class NativeSuggestionTest {
    private final Object listener=new Object(),item=new Object(),context=new Object();
    private NativeSuggestionScope.Row row(String q){return new NativeSuggestionScope.Row(listener,item,context,1,"net_sug_word",q,null,false);}
    private Trace.Frame frame(long id,long parent,Trace.Kind kind){return new Trace.Frame(id,parent,kind);}
    private NativeSuggestionScope.Entry<NativeSuggestionScope.RowToken> enter(NativeSuggestionScope s,NativeSuggestionScope.Row r){return s.enterRow(r,frame(1,0,Trace.Kind.NATIVE_ROW));}
    private NativeSuggestionScope.Entry<NativeSuggestionScope.Hop> bridge(NativeSuggestionScope s,NativeSuggestionScope.Row r){return s.enterBridge(context,r.query(),"sug_page",false,frame(2,1,Trace.Kind.SUGGEST_NATIVE),r);}
    private NativeSuggestionScope.Claim claim(NativeSuggestionScope s,NativeSuggestionScope.Row r){return s.claim(context,r.query(),"sug_page","",false,frame(3,2,Trace.Kind.QUERY),r);}
    @Test public void verifiedRowBridgeAndRawQueryCanClaimOnce(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("中文 % & # 🦉");var rt=enter(s,r);assertEquals(NativeSuggestionScope.Reason.ACCEPTED,rt.reason());var h=bridge(s,r);assertEquals(NativeSuggestionScope.Reason.ACCEPTED,h.reason());var c=claim(s,r);assertNotNull(c.permit());assertTrue(s.live(c.permit()));assertNull(claim(s,r).permit());s.exitBridge(h.token());assertFalse(s.live(c.permit()));s.exitRow(rt.token());assertNull(s.current());}
    @Test public void sugPageAloneStillCannotAuthorize(){assertFalse(QueryScope.allows("sug_page","",false));assertNull(claim(new NativeSuggestionScope(),row("fixed")).permit());}
    @Test public void genericNativeBridgeOutsideRowDoesNotQualify(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");var h=bridge(s,r);assertEquals(NativeSuggestionScope.Reason.NO_ROW,h.reason());assertNull(claim(s,r).permit());s.exitBridge(h.token());}
    @Test public void localAppsContactsSettingsServicesAiAndUnknownTypesFail(){for(String type:new String[]{"local_app","local_settings","local_contact","contact_person","local_function","net_app_store","service","aisearch","onesearch","unknown"})assertEquals(type,NativeSuggestionScope.Reason.WRONG_TYPE,NativeSuggestionScope.qualifies(new NativeSuggestionScope.Row(listener,item,context,1,type,"fixed",null,false)));}
    @Test public void categoryBranchZeroAndUnverifiedVariantsFail(){for(int branch:new int[]{0,2,-1})assertEquals(NativeSuggestionScope.Reason.WRONG_BRANCH,NativeSuggestionScope.qualifies(new NativeSuggestionScope.Row(listener,item,context,branch,"net_sug_word","fixed",null,false)));}
    @Test public void appNovelOrOtherCategoryOnQueryRowIsConservativelyNative(){for(String category:new String[]{"app","novel","other"})assertEquals(NativeSuggestionScope.Reason.CATEGORY,NativeSuggestionScope.qualifies(new NativeSuggestionScope.Row(listener,item,context,1,"net_sug_word","fixed",category,false)));}
    @Test public void payloadPresenceCannotBeOverriddenByTypeName(){assertEquals(NativeSuggestionScope.Reason.SPECIAL_ITEM,NativeSuggestionScope.qualifies(new NativeSuggestionScope.Row(listener,item,context,1,"net_sug_word","fixed",null,true)));}
    @Test public void directUrlsProtocolsAndEmptyQueriesFail(){for(String q:new String[]{"https://www.baidu.com/s?wd=fixed","HTTP://example.test/","intent://x","market://x","tel:123","content://private","file:///x","//example.test/x","www.example.test","/settings","  ","bad\uD800"})assertEquals(q,NativeSuggestionScope.Reason.NOT_TEXT_QUERY,NativeSuggestionScope.qualifies(row(q)));}
    @Test public void selectedTitleIsNotReplacedByTypedInputOrDecodedUrl(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("选中的完整建议 %26 &");enter(s,r);bridge(s,r);assertEquals(NativeSuggestionScope.Reason.WRONG_QUERY_ARGS,s.claim(context,"框内原始输入","sug_page","",false,frame(3,2,Trace.Kind.QUERY),r).reason());}
    @Test public void staleItemTitleTypeOrIdentityCannotClaim(){for(var fresh:new NativeSuggestionScope.Row[]{row("changed"),new NativeSuggestionScope.Row(listener,new Object(),context,1,"net_sug_word","fixed",null,false),new NativeSuggestionScope.Row(listener,item,context,1,"local_app","fixed",null,false)}){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");enter(s,r);bridge(s,r);assertEquals(NativeSuggestionScope.Reason.STALE_ROW,s.claim(context,"fixed","sug_page","",false,frame(3,2,Trace.Kind.QUERY),fresh).reason());}}
    @Test public void wrongBridgeQuerySourceContextAiOrParentIsDenied(){for(int bad=0;bad<5;bad++){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");enter(s,r);var h=s.enterBridge(bad==0?new Object():context,bad==1?"different":"fixed",bad==2?"webview":"sug_page",bad==3,frame(2,bad==4?99:1,Trace.Kind.SUGGEST_NATIVE),r);assertNotEquals(NativeSuggestionScope.Reason.ACCEPTED,h.reason());assertNull(claim(s,r).permit());}}
    @Test public void directAiWrongSourceAndWrongQueryParentAreDenied(){for(int bad=0;bad<4;bad++){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");enter(s,r);bridge(s,r);var c=s.claim(context,"fixed",bad==0?"webview":"sug_page",bad==1?"https://example.test":"",bad==2,frame(3,bad==3?99:2,Trace.Kind.QUERY),r);assertNull(c.permit());}}
    @Test public void bridgeCannotOpenSecondTicketWithinSameClick(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");enter(s,r);var h=bridge(s,r);s.exitBridge(h.token());assertEquals(NativeSuggestionScope.Reason.ALREADY_USED,bridge(s,r).reason());}
    @Test public void asynchronousQueryCannotInheritPermit() throws Exception {NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");enter(s,r);bridge(s,r);AtomicReference<NativeSuggestionScope.Claim> other=new AtomicReference<>();Thread thread=new Thread(()->other.set(claim(s,r)));thread.start();thread.join();assertNull(other.get().permit());assertNotNull(claim(s,r).permit());}
    @Test public void nestedRowPermanentlyInvalidatesParentUntilExit(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");var parent=enter(s,r);bridge(s,r);var c=claim(s,r);assertTrue(s.live(c.permit()));var child=s.enterRow(r,frame(4,3,Trace.Kind.NATIVE_ROW));assertEquals(NativeSuggestionScope.Reason.NESTED_ROW,child.reason());s.exitRow(child.token());assertFalse(s.live(c.permit()));s.exitRow(parent.token());assertNull(s.current());}
    @Test public void nestedBridgeInvalidatesParentTicket(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");enter(s,r);var h=bridge(s,r);var c=claim(s,r);assertTrue(s.live(c.permit()));var nested=s.enterBridge(context,"fixed","sug_page",false,frame(4,3,Trace.Kind.SUGGEST_NATIVE),r);s.exitBridge(nested.token());assertFalse(s.live(c.permit()));s.exitBridge(h.token());}
    @Test public void originalExceptionStillCleansScopeWithoutReplayingClick(){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("fixed");AtomicInteger clicks=new AtomicInteger();Error expected=new Error("fixture");try{var rt=enter(s,r);try{var h=bridge(s,r);try{clicks.incrementAndGet();throw expected;}finally{s.exitBridge(h.token());}}finally{s.exitRow(rt.token());}}catch(Error actual){assertSame(expected,actual);}assertEquals(1,clicks.get());assertNull(claim(s,r).permit());assertNull(s.current());assertEquals(NativeSuggestionScope.Reason.ACCEPTED,enter(s,r).reason());}
    @Test public void twoSequentialClicksCanEachGetTheirOwnPermit(){NativeSuggestionScope s=new NativeSuggestionScope();for(String q:new String[]{"first","second"}){var r=row(q);var rt=enter(s,r);var h=bridge(s,r);assertNotNull(claim(s,r).permit());s.exitBridge(h.token());s.exitRow(rt.token());}}
    @Test public void bingGoogleAndBrowserModesUseOriginalEncodingAndDispatcher() throws Throwable {for(EngineChoice choice:new EngineChoice[]{EngineChoice.BING,EngineChoice.GOOGLE})for(boolean browser:new boolean[]{false,true}){NativeSuggestionScope s=new NativeSuggestionScope();var r=row("中文 %&#+ 🦉");var rt=enter(s,r);var h=bridge(s,r);var permit=claim(s,r).permit();assertNotNull(permit);FeatureState f=FeatureState.checked(true,browser,true,choice,1);DecisionLease d=new DecisionLease(f,QueryScope.normalize(r.query()),choice.template,new Object(),new Object());d.templated=true;String generated=choice.template.replace("{searchTerms}",java.net.URLEncoder.encode(d.query,"UTF-8"));assertTrue(d.encoded(choice.template,d.query,generated));assertTrue(d.dispatch(f,d.model,d.item,generated,generated));AtomicInteger web=new AtomicInteger(),nativeRoute=new AtomicInteger();new BrowserDispatcher().run(browser,()->web.incrementAndGet(),()->{nativeRoute.incrementAndGet();return null;},outcome->{});assertEquals(browser?1:0,web.get());assertEquals(browser?0:1,nativeRoute.get());assertTrue(s.live(permit));s.exitBridge(h.token());s.exitRow(rt.token());}}
    @Test public void disabledOrUnreadableConfigurationStillBlocksDecision(){for(FeatureState f:new FeatureState[]{FeatureState.unavailable(),FeatureState.checked(false,true,true)}){DecisionLease d=new DecisionLease(FeatureState.checked(true,true,true),"fixed",EngineChoice.BING.template,new Object(),new Object());d.templated=true;assertTrue(d.encoded(d.template,d.query,SearchUrlPolicy.expected(d.template,d.query)));assertFalse(d.dispatch(f,d.model,d.item,d.output,d.output));}}
    private enum TestOutcome { OUTSIDE_SCOPE }
    @Test public void rejectionCarriesExactQueryCallAndParentWithoutPrivateData(){StringBuilder sink=new StringBuilder();DiagnosticLog log=new DiagnosticLog(sink::append);QueryStatus.emit(log,TestOutcome.OUTSIDE_SCOPE,frame(16,15,Trace.Kind.QUERY),EngineChoice.BING,QueryStatus.Reason.NATIVE_DOMAIN_REQUIRED);String line=sink.toString();assertTrue(line.contains("call=16 parent=15"));assertTrue(line.contains("OUTSIDE_SCOPE"));assertTrue(line.contains("BING"));assertTrue(line.contains("NATIVE_DOMAIN_REQUIRED"));assertFalse(line.contains("call=0"));}
}
